<?php $pageList=query('SELECT * FROM pages ORDER BY id')->fetchAll();$pageEdit=isset($_GET['page_edit'])?query('SELECT * FROM pages WHERE id=?',[(int)$_GET['page_edit']])->fetch():null;?>
<section class="panel admin-panel"><h2><?=e(t('Pages'))?></h2><p class="muted"><?=e(t('Configure widgets under Page layout.'))?></p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th><?=e(t('Title'))?></th><th><?=e(t('Address'))?></th><th><?=e(t('Status'))?></th><th><?=e(t('Actions'))?></th></tr></thead><tbody><?php foreach($pageList as $entry):?><tr><td><?=e($entry['title'])?></td><td><?=e(pageUrl($entry))?></td><td><?=e(t(ucfirst($entry['status'])))?></td><td><div class="admin-row-actions"><a href="/admin/pages?page_edit=<?=$entry['id']?>"><?=e(t('Edit'))?></a><a href="/admin/pages/layout?context=<?=e($entry['kind']==='custom'?'page:'.$entry['id']:$entry['kind'])?>"><?=e(t('Edit layout'))?></a><?php if($entry['status']==='published'):?><a href="<?=e(pageUrl($entry))?>"><?=e(t('View'))?></a><?php endif;?></div></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel admin-panel"><h2><?=e(t($pageEdit?'Edit page':'New page'))?></h2><form class="settings-form" data-admin-action="page_save"><input type="hidden" name="id" value="<?=e($pageEdit['id']??'')?>"><label><?=e(t('Title'))?><input name="title" maxlength="200" required value="<?=e($pageEdit['title']??'')?>"></label><label><?=e(t('Address slug'))?><input name="slug" pattern="[a-z0-9][a-z0-9-]{0,79}" maxlength="80" required placeholder="my-page" value="<?=e($pageEdit['slug']??'')?>"></label><label><?=e(t('Status'))?><select name="status"><option value="published" <?=($pageEdit['status']??'')==='published'?'selected':''?>><?=e(t('Published'))?></option><option value="draft" <?=($pageEdit['status']??'draft')==='draft'?'selected':''?>><?=e(t('Draft'))?></option></select></label><button type="submit" class="button"><?=e(t('Save changes'))?></button></form></section>
